package com.agriconnect.order;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.jdbc.support.GeneratedKeyHolder;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders")class OrderController{private final JdbcClient db;private final CropInventoryClient crop;OrderController(JdbcClient d,CropInventoryClient c){db=d;crop=c;}private long uid(){return Long.parseLong(SecurityContextHolder.getContext().getAuthentication().getName());}private String sel(){return"select id,buyer_id as \"buyerId\",total_amount as \"totalAmount\",status,order_date as \"orderDate\",created_at as \"createdAt\",delivery_address as \"deliveryAddress\",return_state as \"returnState\" from orders";}
@GetMapping Map<String,Object>all(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){var a=SecurityContextHolder.getContext().getAuthentication();boolean admin=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN")||x.getAuthority().equals("ROLE_LOGISTICS"));String where=admin?"":" where buyer_id=:u";var q=db.sql(sel()+where+" order by id desc limit :s offset :o").param("s",size).param("o",page*size);if(!admin)q=q.param("u",uid());var rows=q.query().listOfRows();return Map.of("content",rows,"number",page,"size",size,"totalElements",rows.size(),"totalPages",rows.isEmpty()?0:1,"first",true,"last",true,"empty",rows.isEmpty());}
@GetMapping("/status-counts")Map<String,Long>statusCounts(){var a=SecurityContextHolder.getContext().getAuthentication();Set<String>roles=new HashSet<>();a.getAuthorities().forEach(x->roles.add(x.getAuthority()));String sql;boolean bind=!roles.contains("ROLE_ADMIN")&&!roles.contains("ROLE_LOGISTICS");if(roles.contains("ROLE_FARMER"))sql="select o.status,count(distinct o.id) n from orders o join order_items i on i.order_id=o.id where i.farmer_id=:u group by o.status";else if(bind)sql="select status,count(*) n from orders where buyer_id=:u group by status";else sql="select status,count(*) n from orders group by status";var q=db.sql(sql);if(bind)q=q.param("u",uid());Map<String,Long>result=new LinkedHashMap<>();for(String s:List.of("PENDING","CONFIRMED","PACKING","SHIPPING","DELIVERED","CANCELLED"))result.put(s,0L);q.query().listOfRows().forEach(r->result.put(String.valueOf(r.get("status")),((Number)r.get("n")).longValue()));return result;}
@GetMapping("/my")@PreAuthorize("hasRole('BUYER')")Map<String,Object>mine(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return all(page,size);}@GetMapping("/{id}")Map<String,Object>one(@PathVariable long id){var x=db.sql(sel()+" where id=:id").param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"ORDER_NOT_FOUND","Order not found"));return x;}
@PostMapping("/checkout")@PreAuthorize("hasRole('BUYER')")ResponseEntity<?>checkout(@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>x){String hash=hash(x.toString());var old=db.sql("select request_hash,response_body from idempotency_records where idempotency_key=:k and command='CHECKOUT' and user_id=:u").param("k",key).param("u",uid()).query().listOfRows().stream().findFirst();if(old.isPresent()){if(!hash.equals(old.get().get("request_hash")))throw new DomainException(HttpStatus.CONFLICT,"IDEMPOTENCY_KEY_REUSED","Idempotency key was reused with a different request");return ResponseEntity.ok(one(Long.parseLong(String.valueOf(old.get().get("response_body")))));}List<Map<String,Object>>items=(List<Map<String,Object>>)x.get("items");List<Number>lockIds=(List<Number>)x.get("cropLockIds");if(items==null||items.isEmpty()||lockIds==null)throw new DomainException(HttpStatus.BAD_REQUEST,"INVALID_ORDER","Checkout items and crop locks are required");List<Map<String,Object>>locks=lockIds.stream().map(n->new CropLockController(db,crop).one(n.longValue())).toList();long orderId;try{orderId=saveOrder(x,items,locks);}catch(RuntimeException e){locks.forEach(l->{try{crop.release(UUID.fromString(String.valueOf(l.get("inventoryReservationId"))));}catch(Exception ignored){}});throw e;}for(Map<String,Object>l:locks){crop.commit(UUID.fromString(String.valueOf(l.get("inventoryReservationId"))));db.sql("update crop_locks set status='CONVERTED' where id=:id").param("id",l.get("id")).update();}db.sql("insert into idempotency_records(idempotency_key,command,user_id,request_hash,response_status,response_body,state)values(:k,'CHECKOUT',:u,:h,201,:b,'COMPLETED')").param("k",key).param("u",uid()).param("h",hash).param("b",String.valueOf(orderId)).update();return ResponseEntity.status(201).body(one(orderId));}
@Transactional long saveOrder(Map<String,Object>x,List<Map<String,Object>>items,List<Map<String,Object>>locks){var kh=new GeneratedKeyHolder();db.sql("insert into orders(buyer_id,total_amount,status,delivery_address)values(:u,:t,'PENDING',:a)").param("u",uid()).param("t",x.getOrDefault("totalAmount",0)).param("a",x.get("deliveryAddress")).update(kh,"id");long id=kh.getKey().longValue();for(Map<String,Object>i:items){long batch=((Number)i.get("batchId")).longValue();Map<String,Object>lock=locks.stream().filter(l->((Number)l.get("batchId")).longValue()==batch).findFirst().orElseThrow(()->new DomainException(HttpStatus.BAD_REQUEST,"CROP_LOCK_MISMATCH","Crop locks must match checkout items"));BigDecimal q=new BigDecimal(String.valueOf(i.get("quantity"))),price=new BigDecimal(String.valueOf(i.get("unitPrice")));Map<String,Object>b=crop.batch(batch);db.sql("insert into order_items(order_id,batch_id,farmer_id,inventory_reservation_id,quantity,unit_price,subtotal)values(:o,:b,:f,:r,:q,:p,:s)").param("o",id).param("b",batch).param("f",b.get("farmerId")).param("r",UUID.fromString(String.valueOf(lock.get("inventoryReservationId")))).param("q",q).param("p",price).param("s",q.multiply(price)).update();}return id;}
@PatchMapping("/{id}/status")Map<String,Object>status(@PathVariable long id,@RequestBody Map<String,Object>x){String next=String.valueOf(x.get("status"));Map<String,Object>o=one(id);String cur=String.valueOf(o.get("status"));if(!valid(cur,next))throw new DomainException(HttpStatus.CONFLICT,"INVALID_ORDER_STATUS_TRANSITION","Invalid order status transition from "+cur+" to "+next);db.sql("update orders set status=:s,return_state=case when :s='CANCELLED' then 'ADMIN_REVIEW' else return_state end where id=:id").param("s",next).param("id",id).update();db.sql("insert into order_status_history(order_id,from_status,to_status,changed_by)values(:id,:f,:t,:u)").param("id",id).param("f",cur).param("t",next).param("u",uid()).update();return one(id);}
private boolean valid(String a,String b){return switch(a){case"PENDING"->Set.of("CONFIRMED","CANCELLED").contains(b);case"CONFIRMED"->Set.of("PACKING","CANCELLED").contains(b);case"PACKING"->b.equals("SHIPPING");case"SHIPPING"->b.equals("DELIVERED");default->false;};}private String hash(String s){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
